const timelineEvents=[{year:"c. 321 BCE",title:"Chandragupta Maurya rises to power",description:"After overthrowing the Nanda dynasty, Chandragupta established the Maurya Empire and created a new imperial order."},{year:"c. 305 BCE",title:"Confrontation with Seleucus",description:"The Mauryas secured western territories through diplomacy and warfare, gaining influence across the northwest."},{year:"c. 298–273 BCE",title:"Bindusara expands the realm",description:"The empire grew further south and consolidated administration through provincial governance."},{year:"c. 268–232 BCE",title:"Ashoka transforms the empire",description:"Ashoka embraced Dharma, propagated Buddhism, and issued rock and pillar edicts across the subcontinent."},{year:"c. 185 BCE",title:"Decline and succession",description:"After Ashoka, the Maurya Empire weakened and eventually fell to the rise of the Shunga dynasty."}],galleryItems=[{title:"Ashoka Pillar",description:"Mauryan pillars symbolized imperial justice, statecraft, and the spread of royal ideals.",imageUrl:"../assets/Ashoka.png"},{title:"Pataliputra City",description:"The capital reflected a planned urban design suited to administration, trade, and military control.",imageUrl:"../assets/ancient_india_illustration.png"},{title:"Mauryan Legacy",description:"The dynasty shaped later political thought through discipline, taxation, and public communication.",imageUrl:"../assets/coinhero.jpeg"}];function renderTimeline(){const e=document.getElementById("timeline-list");e&&(e.innerHTML=timelineEvents.map(e=>`\n    <div class="timeline-card">\n      <h3>${e.year} — ${e.title}</h3>\n      <p>${e.description}</p>\n    </div>\n  `).join(""))}function renderGallery(){const e=document.getElementById("gallery-grid");e&&(e.innerHTML=galleryItems.map(e=>`\n    <article class="gallery-card">\n      <div class="gallery-image">\n        <img src="${e.imageUrl}" alt="${e.title}" />\n      </div>\n      <h3>${e.title}</h3>\n      <p>${e.description}</p>\n    </article>\n  `).join(""))}document.addEventListener("DOMContentLoaded",()=>{renderTimeline(),renderGallery()});